<?php

namespace App\Http\Middleware;

use Closure;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\URL;
use Symfony\Component\HttpFoundation\Response;

/**
 * The service is proxied under /sso, so absolute URLs generated by the framework
 * must carry that path and the public scheme even though we speak plain HTTP on
 * the container network.
 */
class ForceHttpsRootUrl
{
    public function handle(Request $request, Closure $next): Response
    {
        if (! config('sso.force_root_url', true)) {
            return $next($request);
        }

        $scheme = (string) config('sso.url_scheme', 'https');
        $path = trim((string) config('sso.session_path', '/sso'), '/');

        $root = $scheme.'://'.$request->getHost().($path === '' ? '' : '/'.$path);
        URL::forceRootUrl($root);

        if ($scheme === 'https') {
            URL::forceScheme('https');
        }

        return $next($request);
    }
}
